import React, { useEffect, useState, useRef } from "react";

import { getStore,  gen16CodeId,  ObjectKeys,  dayNamesES, qryStore, fetchEncryptStream, compareJSON, getWeekDetails, getWeekDetailsByNUm } from "../../../stores/Utils";

import "./dashboard.css"
import { OpenModal } from "../../../components/DialogHRM";
import { getall_timecard } from "../services/server_fetching";
import { ContainerElasticView, SvgIcon_Cmpt } from "../../../components";
import { parseTimeH, parseWeekrange } from "./ViewPaystub";
import DeleteAlert from "../../Inventory/component/deleteAlert";

const Svg = SvgIcon_Cmpt();



let errCodes = {
	1: {color: "var(--hrm_palette-success-fg)", icon: "check_circle"},
	2: {color: "rgb(254, 120, 23)", icon: "reload"},
	3: {color: "var(--hrm_palette-selected-nav-text)", icon: "alert"},
}




const TimeCardItem  = ({ data, add, handleRefreshAll }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			// let frm2 = {"firstName":"Belisario","lastName":"Gonzalez Arevalo","genre":"Male","dateOfBirth":"06/02/1976","placeOfBirth":{"city":"Holguin","state":"Holguin"},"currentAddress":{"No":"4307","street":"Estate Dr","city":"Louisville","state":"Kentucky","zipcode":"40216"},"dob":202536000000}
			//updStore(frmNm, frm2);
			set_obs(gen16CodeId())
		}
	});

	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	

	const refreshAccs =  () => {
		getall_timecard(updObs)
	}


	
	const addTimeCard =  () => {
		let nObj = {...data}
		nObj["time_cardId"] =  gen16CodeId();
		let bdyq2 = {...getStore(qryStore())?.add_time_card};
		bdyq2.params = { 
			businessId:  getStore("profileUser")?.businessId
		};
		bdyq2.form=nObj;
		fetch2Server(bdyq2)
	}

	const openSubMayorModal =  (func, upd) => {
		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "40vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
		let errCode = upd?2:1;
		let theme = upd?"orange":"green";
		let titleCm = <div className="_dsplFlx ">
			<div className="centerBx">
				<Svg
					name={errCodes[errCode]?.icon} 
					color={errCodes[errCode]?.color }
				/>
			</div>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{upd === 1? "Desea Actualizar esta tarjeta de horario!!!" : "Desea Agregar esta tarjeta de horario!!!"}
			</h4>
		</div>
		modaldata["content"] = <DeleteAlert
			label={titleCm} 
			labelColor={errCodes[errCode]?.color } 
			body={" "} 
			btnConfirm={"OK"}
			theme={theme}
			confirm={func}
		/>
		OpenModal(modaldata);
	}

	
	const fetch2Server = async (bdyq2) => {
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td) {
			handleRefreshAll();
		}
	}




	let wKs = data?.week + "_" + data?.userTC;

	let allowAdd = !getStore("timecard_gorups_week")?.[wKs]?.week;
	let diff = compareJSON(["hourly"], data, getStore("timecard_gorups_week")?.[wKs])
			
	let errorCode = 1;

	
	if(add){
		if(!allowAdd){
			errorCode = 2;
			if(!diff.hasChange){
				return null;
			}
		}
		else{
			errorCode = 3;
		}
	}
	
	



	const updTimeCard =  () => {
		let nObj = {...getStore("timecard_gorups_week")?.[wKs]}
		let bdyq2 = {...getStore(qryStore())?.upd_time_card};
		bdyq2.params = { 
			businessId:  getStore("profileUser")?.businessId,
			time_cardId: nObj["time_cardId"]
		};
		bdyq2.data2update={hourly: data.hourly};
		// console.log(bdyq2)
		fetch2Server(bdyq2)
	}

	let weekD = getWeekDetailsByNUm(data?.week*1-1);

	
	const rmvOperatIds =  () => {
		let nObj = {...getStore("timecard_gorups_week")?.[wKs]}
		let bdyq2 = {...getStore(qryStore())?.rmv_time_card};
		bdyq2.params = { 
			businessId:  getStore("profileUser")?.businessId,
			time_cardId: nObj["time_cardId"]
		};
		console.log(bdyq2)
		fetch2Server(bdyq2)
	}
	

	const OpenDeleteAlert =  () => {
		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "40vh";
		
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
		let titleCm = <div className="_dsplFlx ">
			<div className="centerBx">
				<Svg 
					name={"alert"} 
					color={"var(--hrm_palette-selected-nav-text)"}
				/>
			</div>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"Peligro va a eliminar un TimeCard!!!"}
			</h4>
		</div>
		modaldata["content"] = <DeleteAlert 
			label={titleCm} 
			labelColor={"var(--hrm_palette-selected-nav-text)"} 
			body={"debe saber que no podra recuperarlo"} 
			btnConfirm={"OK"}
			confirm={rmvOperatIds}
		/>
		OpenModal(modaldata);
	}




	return (
		<div className="item_acc  item_box employee_header" style={{margin: 9}}>
			<div className="_dsplFlx">
				<div className="_dsplFlx">
					<div className="icon_revision" >
						<Svg 
							name={errCodes[errorCode]?.icon} 
							color={errCodes[errorCode]?.color }
						/>
					</div>
					
					<div className="name centerBx">
						{}
					</div>
					<div className="flexSpace"/>
					<div className="empl-name centerBx" style={{marginLeft: 13}}>
						{getStore("employees_ctIds")?.[data?.userTC]?.name? getStore("employees_ctIds")?.[data?.userTC]?.name : data?.userTC}
					</div>

					
				</div>
				<div className="flexSpace"/>
				<div className="name centerBx " style={{fontSize: 13}}>
					
					{parseWeekrange(weekD*1)}
				</div>
				
				
				{errorCode === 3?
				<div className=" addSbAcc purple" onClick={()=>openSubMayorModal(addTimeCard)}>
					Agregar
				</div>
				:null}

				{errorCode === 2?
				<div className=" addSbAcc purple" onClick={()=>openSubMayorModal(updTimeCard,1)}>
					Update
				</div>
				:null}
				{errorCode === 1?
				<div className="tr_bar_5" style={{marginLeft: 13}}>
					<div className="icon tr_bar_5" onClick={OpenDeleteAlert}>
						<Svg name={"outline_delete"} color={"#c62828"}/>
					</div>
				</div>
				:null}
			</div>
			<ContainerElasticView >
				<div className="_dsplFlx spaceAround flxWrp card_2_dark"  style={{margin: "6px 0 6px"}} >
					{data?.["hourly"] && ObjectKeys(data?.["hourly"]).map((day,inD)=>{
						let dayItm = data?.["hourly"]?.[day];
						return (
							<TimeUpdateDay
								key={day}
								dayName={day}
								index={inD}
								data={dayItm}
							/>
						)
					})}
				</div>
			</ContainerElasticView>
		</div>
	)
}
export default TimeCardItem;




const TimeUpdateDay  = ({
	data,
	index,
	dayName,
	
 }) => {

	

	return (
		<>
		{index>0?
		<>
			<div className="flexSpace"/>
			<div className="left_border"/>
			<div className="flexSpace"/>
		</>
		:null}
		<div className={`lbl_h_dtls`}  style={{marginTop:8, textAlign: "left"}} >
			<div className="dayHour _dsplFlx">
				<div className="flexSpace"/>
				<div style={{marginRight: 12}}>
					{`${dayNamesES[dayName]}`}
				</div>
				<div className="flexSpace"/>
			</div>
			<div className="_dsplFlx information_detail "  >
				<div className="flexSpace"/>
				<TimeUpdateView 
					data={data} 
					field={"start"}
					icon={"startMode"}
				/>
				<div className="flexSpace"/>
				-
				<div className="flexSpace"/>
				<TimeUpdateView 
					data={data} 
					field={"end"}
					icon={"endMode"}
				/>
				<div className="flexSpace"/>
			</div>
		</div>
		</>
		)
 }


let iconsTC = {
	33: "fingerprint",
	52: "face-recognition",
	35: "cards"
}

const TimeUpdateView  = ({
	data,
	field,
	icon
 }) => {


	let iconSv = iconsTC?.[data?.[icon]?.[0]];
	
	return (

		<div   >
			<div className=" payments hour" >
				<Svg
					name={iconSv||""} 
					size={22}
					color={"var(--hrm_palette-blue-purple)"}
				/>
				{parseTimeH(data?.[field])}
			</div>
		</div>

	) 
 }
